9		"miniflux.app/v2/internal/timezone"
10	)
11	
12	// User represents a user in the system.
13	type User struct {
14		ID                              int64      `json:"id"`
15		Username                        string     `json:"username"`
16		Password                        string     `json:"-"`
17		Theme                           string     `json:"theme"`
18		Language                        string     `json:"language"`
19		Timezone                        string     `json:"timezone"`
20		EntryDirection                  string     `json:"entry_sorting_direction"`
21		EntryOrder                      string     `json:"entry_sorting_order"`
22		Stylesheet                      string     `json:"stylesheet"`
23		CustomJS                        string     `json:"custom_js"`
24		ExternalFontHosts               string     `json:"external_font_hosts"`
25		GoogleID                        string     `json:"google_id"`
26		OpenIDConnectID                 string     `json:"openid_connect_id"`
27		EntriesPerPage                  int        `json:"entries_per_page"`
28		GestureNav                      string     `json:"gesture_nav"`
29		LastLoginAt                     *time.Time `json:"last_login_at"`
30		DisplayMode                     string     `json:"display_mode"`
31		DefaultReadingSpeed             int        `json:"default_reading_speed"`
32		CJKReadingSpeed                 int        `json:"cjk_reading_speed"`
33		DefaultHomePage                 string     `json:"default_home_page"`
34		CategoriesSortingOrder          string     `json:"categories_sorting_order"`
35		MediaPlaybackRate               float64    `json:"media_playback_rate"`
36		BlockFilterEntryRules           string     `json:"block_filter_entry_rules"`
37		KeepFilterEntryRules            string     `json:"keep_filter_entry_rules"`
38		MarkReadOnView                  bool       `json:"mark_read_on_view"`
39		MarkReadOnMediaPlayerCompletion bool       `json:"mark_read_on_media_player_completion"`
40		AlwaysOpenExternalLinks         bool       `json:"always_open_external_links"`
41		OpenExternalLinksInNewTab       bool       `json:"open_external_links_in_new_tab"`
42		KeyboardShortcuts               bool       `json:"keyboard_shortcuts"`
43		ShowReadingTime                 bool       `json:"show_reading_time"`
44		EntrySwipe                      bool       `json:"entry_swipe"`
45		IsAdmin                         bool       `json:"is_admin"`
46	}
47	
48	// UserCreationRequest represents the request to create a user.
49	type UserCreationRequest struct {
50		Username        string `json:"username"`
