4	package api // import "miniflux.app/v2/internal/api"
5	
6	import (
7		json_parser "encoding/json"
8		"errors"
9		"net/http"
10	
11		"miniflux.app/v2/internal/http/request"
12		"miniflux.app/v2/internal/http/response"
13		"miniflux.app/v2/internal/model"
14		"miniflux.app/v2/internal/validator"
15	)
16	
17	func (h *handler) currentUserHandler(w http.ResponseWriter, r *http.Request) {
18		user, err := h.store.UserByID(request.UserID(r))
19		if err != nil {
20			response.JSONServerError(w, r, err)
21			return
22		}
23	
24		if user == nil {
25			response.JSONNotFound(w, r)
26			return
27		}
28	
29		response.JSON(w, r, user)
30	}
31	
32	func (h *handler) createUserHandler(w http.ResponseWriter, r *http.Request) {
33		if !request.IsAdminUser(r) {
34			response.JSONForbidden(w, r)
35			return
36		}
37	
38		var userCreationRequest model.UserCreationRequest
39		if err := json_parser.NewDecoder(r.Body).Decode(&userCreationRequest); err != nil {
40			response.JSONBadRequest(w, r, err)
41			return
42		}
43	
44		if validationErr := validator.ValidateUserCreationWithPassword(h.store, &userCreationRequest); validationErr != nil {
45			response.JSONBadRequest(w, r, validationErr.Error())
46			return
47		}
48	
49		user, err := h.store.CreateUser(&userCreationRequest)
50		if err != nil {
51			response.JSONServerError(w, r, err)
52			return
53		}
54	
55		response.JSONCreated(w, r, user)
56	}
57	
58	func (h *handler) updateUserHandler(w http.ResponseWriter, r *http.Request) {
59		userID := request.RouteInt64Param(r, "userID")
60		if userID == 0 {
61			response.JSONBadRequest(w, r, errors.New("invalid user ID"))
62			return
63		}
64	
65		var userModificationRequest model.UserModificationRequest
66		if err := json_parser.NewDecoder(r.Body).Decode(&userModificationRequest); err != nil {
67			response.JSONBadRequest(w, r, err)
68			return
69		}
70	
71		originalUser, err := h.store.UserByID(userID)
72		if err != nil {
73			response.JSONServerError(w, r, err)
74			return
75		}
76	
77		if originalUser == nil {
78			response.JSONNotFound(w, r)
79			return
80		}
81	
82		if !request.IsAdminUser(r) {
83			if originalUser.ID != request.UserID(r) {
84				response.JSONForbidden(w, r)
85				return
86			}
87	
88			if userModificationRequest.IsAdmin != nil && *userModificationRequest.IsAdmin {
89				response.JSONBadRequest(w, r, errors.New("only administrators can change permissions of standard users"))
90				return
91			}
92		}
93	
94		if validationErr := validator.ValidateUserModification(h.store, originalUser.ID, &userModificationRequest); validationErr != nil {
95			response.JSONBadRequest(w, r, validationErr.Error())
96			return
97		}
98	
99		userModificationRequest.Patch(originalUser)
100		if err = h.store.UpdateUser(originalUser); err != nil {
101			response.JSONServerError(w, r, err)
102			return
103		}
104	
105		if userModificationRequest.Password != nil {
106			if err := h.store.RemoveUserWebSessionsExcept(originalUser.ID, ""); err != nil {
107				response.JSONServerError(w, r, err)
108				return
109			}
110		}
111	
112		response.JSONCreated(w, r, originalUser)
113	}
114	
115	func (h *handler) markUserAsReadHandler(w http.ResponseWriter, r *http.Request) {
116		userID := request.RouteInt64Param(r, "userID")
117		if userID == 0 {
118			response.JSONBadRequest(w, r, errors.New("invalid user ID"))
119			return
120		}
121	
122		if userID != request.UserID(r) {
123			response.JSONForbidden(w, r)
124			return
125		}
126	
127		user, err := h.store.UserByID(userID)
128		if err != nil {
129			response.JSONServerError(w, r, err)
130			return
131		}
132	
133		if user == nil {
134			response.JSONNotFound(w, r)
135			return
136		}
137	
138		if err := h.store.MarkAllAsRead(userID); err != nil {
139			response.JSONServerError(w, r, err)
140			return
141		}
142	
143		response.NoContent(w, r)
144	}
145	
146	func (h *handler) getIntegrationsStatusHandler(w http.ResponseWriter, r *http.Request) {
147		userID := request.UserID(r)
148		user, err := h.store.UserByID(userID)
149		if err != nil {
150			response.JSONServerError(w, r, err)
151			return
152		}
153	
154		if user == nil {
155			response.JSONNotFound(w, r)
156			return
157		}
158	
159		hasIntegrations := h.store.HasSaveEntry(userID)
160	
161		response.JSON(w, r, integrationsStatusResponse{HasIntegrations: hasIntegrations})
162	}
163	
164	func (h *handler) usersHandler(w http.ResponseWriter, r *http.Request) {
165		if !request.IsAdminUser(r) {
166			response.JSONForbidden(w, r)
167			return
168		}
169	
170		users, err := h.store.Users()
171		if err != nil {
172			response.JSONServerError(w, r, err)
173			return
174		}
175	
176		users.UseTimezone(request.UserTimezone(r))
177		response.JSON(w, r, users)
178	}
179	
180	func (h *handler) dispatchUserLookupHandler(w http.ResponseWriter, r *http.Request) {
181		identifier := request.RouteStringParam(r, "identifier")
182		userID := request.RouteInt64Param(r, "identifier")
183		if userID > 0 {
184			r.SetPathValue("userID", identifier)
185			h.userByIDHandler(w, r)
186			return
187		}
188	
189		r.SetPathValue("username", identifier)
190		h.userByUsernameHandler(w, r)
191	}
192	
193	func (h *handler) userByIDHandler(w http.ResponseWriter, r *http.Request) {
194		if !request.IsAdminUser(r) {
195			response.JSONForbidden(w, r)
196			return
197		}
198	
199		userID := request.RouteInt64Param(r, "userID")
200		if userID == 0 {
201			response.JSONBadRequest(w, r, errors.New("invalid user ID"))
202			return
203		}
204	
205		user, err := h.store.UserByID(userID)
206		if err != nil {
207			response.JSONServerError(w, r, err)
208			return
209		}
210	
211		if user == nil {
212			response.JSONNotFound(w, r)
213			return
214		}
215	
216		user.UseTimezone(request.UserTimezone(r))
217		response.JSON(w, r, user)
218	}
219	
220	func (h *handler) userByUsernameHandler(w http.ResponseWriter, r *http.Request) {
221		if !request.IsAdminUser(r) {
222			response.JSONForbidden(w, r)
223			return
224		}
225	
226		username := request.RouteStringParam(r, "username")
227		user, err := h.store.UserByUsername(username)
228		if err != nil {
229			response.JSONServerError(w, r, err)
230			return
231		}
232	
233		if user == nil {
234			response.JSONNotFound(w, r)
235			return
236		}
237	
238		response.JSON(w, r, user)
239	}
240	
241	func (h *handler) removeUserHandler(w http.ResponseWriter, r *http.Request) {
242		if !request.IsAdminUser(r) {
243			response.JSONForbidden(w, r)
244			return
245		}
246	
247		userID := request.RouteInt64Param(r, "userID")
248		if userID == 0 {
249			response.JSONBadRequest(w, r, errors.New("invalid user ID"))
250			return
251		}
252	
253		user, err := h.store.UserByID(userID)
254		if err != nil {
255			response.JSONServerError(w, r, err)
256			return
257		}
258	
259		if user == nil {
260			response.JSONNotFound(w, r)
261			return
262		}
263	
264		if user.ID == request.UserID(r) {
265			response.JSONBadRequest(w, r, errors.New("you cannot remove yourself"))
266			return
267		}
268	
269		if err := h.store.RemoveUser(user.ID); err != nil {
270			response.JSONServerError(w, r, err)
271			return
272		}
273	
274		response.NoContent(w, r)
275	}
